import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.2cFhd8Ux.js";const p=JSON.parse('{"title":"Week 14 — Lab and Assignment","description":"","frontmatter":{"source":"weeks/14-evidence-and-responsibility/lab.md"},"headers":[],"relativePath":"weeks/14-evidence-and-responsibility/lab.md","filePath":"weeks/14-evidence-and-responsibility/lab.md"}'),n={name:"weeks/14-evidence-and-responsibility/lab.md"};function r(i,e,l,d,h,c){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="week-14--lab-and-assignment" tabindex="-1">Week 14 — Lab and Assignment <a class="header-anchor" href="#week-14--lab-and-assignment" aria-label="Permalink to &quot;Week 14 — Lab and Assignment&quot;">​</a></h1><blockquote><p>This Lab does two things at once. Examiners run <strong>oral exam 2</strong> in 20-minute slots, and everyone not in a slot works with their team on a structured <strong>final-report sprint</strong>: do exactly what a grader will do with your <code>final</code> tag, and find out now which of your numbers you can&#39;t reproduce.</p></blockquote><p>Bring your team fork, your week 13 retrospective, <code>course/SPEC.md</code>, <code>course/AI_LOG.md</code> and the <a href="./../../project/milestones.html#the-final-report">final report outline</a>. The debate&#39;s lesson applies to your own report: every number needs a source, an uncertainty and an honest limit.</p><h2 id="lab--oral-exam-2-and-the-final-report-sprint-75-min" tabindex="-1">Lab — Oral Exam 2 and the Final-Report Sprint (75 min) <a class="header-anchor" href="#lab--oral-exam-2-and-the-final-report-sprint-75-min" aria-label="Permalink to &quot;Lab — Oral Exam 2 and the Final-Report Sprint (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Everyone not in an exam slot</th><th>Oral exam slots (each examiner)</th></tr></thead><tbody><tr><td>0:00–0:05</td><td>Part 0: setup check and roles</td><td>Examiner prepares</td></tr><tr><td>0:05–0:25</td><td>Part A: the grader&#39;s walk</td><td>Slot 1</td></tr><tr><td>0:25–0:35</td><td>Part B: status against the spec</td><td>Slot 2 (from 0:25)</td></tr><tr><td>0:35–0:50</td><td>Part C: decisions and the claims audit</td><td>Slot 2 continues, slot 3 from 0:45</td></tr><tr><td>0:50–0:55</td><td>Part D (If time): limitations</td><td>Slot 3</td></tr><tr><td>0:55–1:10</td><td>Checkoff (staff also circulate from 0:35)</td><td>Slot 3 ends at 1:05; scoring</td></tr><tr><td>1:10–1:15</td><td>Next steps</td><td></td></tr></tbody></table><p>Slots are 20 minutes: 15 for the exam and 5 to change over and score. The rest of the week&#39;s slots are in office hours and booked times, all inside week 14 (<a href="./../../assessment/oral-exams.html#scheduling">scheduling</a>).</p><h3 id="oral-exam-2-if-you-have-a-slot" tabindex="-1">Oral exam 2: if you have a slot <a class="header-anchor" href="#oral-exam-2-if-you-have-a-slot" aria-label="Permalink to &quot;Oral exam 2: if you have a slot&quot;">​</a></h3><p><strong>What it covers:</strong> your team PRs at M1 and M2, your PR-round PR and reviews, and your assignments from weeks 9–13. Four parts of about 3–4 minutes each: explain your code, modify it live, critique a diff you haven&#39;t seen, and explain an agent trace or eval log (<a href="./../../assessment/oral-exams.html#oral-exam-2-week-14">oral exam 2</a>; <a href="./../../assessment/oral-exams.html#question-types">question types</a>).</p><p><strong>Before your slot</strong> (<a href="./../../assessment/oral-exams.html#students-before-you-arrive">full checklist</a>):</p><ul><li>☐ Your repositories open in a Codespace, with the tests already run once.</li><li>☐ Everything committed, so <code>git restore .</code> undoes the live change in one step.</li><li>☐ Completions off, AI chat panels closed, no AI tabs. If a suggestion appears anyway, ignore it.</li><li>☐ <code>course/AI_LOG.md</code> open, and your PR list in the team fork.</li><li>☐ Be at the exam room two minutes early; tell your team when you&#39;re leaving.</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>🔴 AI off for the whole exam.</strong> Your repositories, a terminal, git, your editor with completions off, the running tests and the <a href="./../../resources/glossary.html">glossary</a> are allowed; nothing else.</p></div><p><strong>There is no retake for oral exam 2,</strong> because week 15 can&#39;t hold exams (Regulation H-1-a). Missed your slot for a recognized reason (Regulation M-1 or M-3)? It&#39;s rescheduled inside week 14 if at all possible, otherwise before the grade deadline, never in week 15 (<a href="./../../assessment/oral-exams.html#retakes-and-make-ups">make-ups</a>). Extra time, written-first, typed answers and the online variant are available (<a href="./../../assessment/oral-exams.html#accommodations">accommodations</a>).</p><p><strong>After your slot,</strong> go back to your team and take your role back. The sprint is built so that any one member can be out for 20 minutes.</p><h3 id="part-0--setup-check-and-roles-core-5-min" tabindex="-1">Part 0 — Setup check and roles (Core, 5 min) <a class="header-anchor" href="#part-0--setup-check-and-roles-core-5-min" aria-label="Permalink to &quot;Part 0 — Setup check and roles (Core, 5 min)&quot;">​</a></h3><ol><li>Find your exam time on the posted list, if you have one.</li><li>Agree four roles. Members with an exam slot take a role that can pause (Decision writer works well). <ul><li><strong>Reproducer:</strong> someone who did <em>not</em> write the README or the CI workflow. They follow the instructions literally, as a grader will.</li><li><strong>Recorder:</strong> keeps the evidence table.</li><li><strong>Spec owner:</strong> keeps the status table.</li><li><strong>Decision writer:</strong> drafts the two engineering decisions.</li></ul></li><li>Record the commit you&#39;re working from:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rev-parse</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --short</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HEAD</span></span></code></pre></div><p>✅ <strong>Checkpoint:</strong> roles assigned, the commit hash written at the top of your draft, and everyone with an exam slot knows when to leave.</p><h3 id="part-a--the-graders-walk-core-20-min" tabindex="-1">Part A — The grader&#39;s walk (Core, 20 min) <a class="header-anchor" href="#part-a--the-graders-walk-core-20-min" aria-label="Permalink to &quot;Part A — The grader&#39;s walk (Core, 20 min)&quot;">​</a></h3><p>At the start of the final exam slot, staff will check out your <code>final</code> tag in a fresh Codespace, build it from your README, and run <strong>one documented command or CI workflow</strong> that reproduces your tests, mutation scores, scans and evals (<a href="./../../project/milestones.html#the-repository-snapshot">the repository snapshot</a>). Do that now, while there&#39;s time to fix what breaks.</p><ol><li><p><strong>The Reproducer opens a brand-new Codespace</strong> on <code>main</code>, not one you&#39;ve used this term:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codespace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [org]/[team-fork] --branch main</span></span></code></pre></div><p>Or use the GitHub page: <strong>Code → Codespaces → New codespace</strong>. A Codespace you&#39;ve worked in for weeks has state the grader&#39;s won&#39;t: installed packages, cached builds, a <code>.env</code>.</p></li><li><p><strong>Follow the README literally.</strong> Every step you had to guess, every missing command, every version you had to change is a README bug. The Recorder writes each one down; fix them in the assignment.</p></li><li><p><strong>Run the one documented command.</strong> If you don&#39;t have one yet, that&#39;s your first fix: a script or a workflow that runs everything a number in your report comes from.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[your documented command, e.g. npm run course:check]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --branch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --limit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span></span></code></pre></div><p>Mutation runs can take a long time on a large codebase. Run them on the changed modules only (that&#39;s what your report claims), or start the run now and continue with Part B. Evals run on recorded responses only: the grader must not need an API key.</p></li><li><p><strong>Fill in the evidence table</strong>, one row for every number your report will contain:</p><table tabindex="0"><thead><tr><th>#</th><th>Number in the report</th><th>Where it comes from (command, CI run, file)</th><th>Fresh-run value (observed)</th><th>Value in your notes</th><th>Same?</th></tr></thead><tbody><tr><td>1</td><td>Mutation score of <code>[module]</code></td><td><code>[command]</code></td><td></td><td></td><td></td></tr><tr><td>2</td><td>Tests passing</td><td>CI run on <code>[commit]</code></td><td></td><td></td><td></td></tr><tr><td>3</td><td>Median review time for agent PRs (week 13)</td><td><code>course/RETROSPECTIVE.md</code></td><td></td><td></td><td></td></tr></tbody></table></li><li><p><strong>For every mismatch, decide:</strong> fix the check, fix the number, or explain the difference in the report (a flaky test, a nondeterministic eval, a provider switch you logged).</p></li></ol><p>✅ <strong>Checkpoint:</strong> the fresh Codespace built from the README; the one command ran; every number in the report has a row with an observed value, or a written reason it has none.</p><p><strong>Troubleshooting.</strong></p><ul><li><strong>The Codespace build fails on a version:</strong> pin the version in the dev container configuration rather than in a README sentence; the grader won&#39;t read the sentence (<a href="./../../resources/troubleshooting.html#the-class-codebase-wont-build">class codebase won&#39;t build</a>).</li><li><strong>CI passes but the local run fails, or the reverse:</strong> compare the CI workflow&#39;s steps with your README&#39;s, line by line. They should be the same commands.</li><li><strong>The CI workflow needs a secret:</strong> a grader&#39;s run won&#39;t have it. Make the reproducible path work without secrets (recorded responses, no deploy step).</li><li><strong>Out of Codespace hours:</strong> pair on a teammate&#39;s, or use a dev container locally (<a href="./../../resources/troubleshooting.html#my-codespace-wont-start-or-im-out-of-hours">troubleshooting</a>).</li></ul><h3 id="part-b--status-against-the-spec-core-10-min" tabindex="-1">Part B — Status against the spec (Core, 10 min) <a class="header-anchor" href="#part-b--status-against-the-spec-core-10-min" aria-label="Permalink to &quot;Part B — Status against the spec (Core, 10 min)&quot;">​</a></h3><p>The Spec owner goes through <code>course/SPEC.md</code> criterion by criterion. This becomes section 2 of the report.</p><table tabindex="0"><thead><tr><th>Criterion (from <code>SPEC.md</code>)</th><th>Status (met, partial, not met)</th><th>Evidence (test name, CI run, demo step)</th><th>Would the evidence fail without the change?</th></tr></thead><tbody><tr><td>WHEN [trigger] THE [system] SHALL [response]</td><td></td><td></td><td></td></tr></tbody></table><p>Three rules:</p><ul><li><strong>&quot;Met&quot; needs a check that would fail without your code.</strong> A test that passes on the old code is not evidence for the new behavior.</li><li><strong>&quot;Partial&quot; says what&#39;s missing.</strong></li><li><strong>&quot;Not met&quot; is an honest answer.</strong> It costs less than a claim that falls apart during the defense, where the demo runs on the tagged commit in front of the room.</li></ul><p>✅ <strong>Checkpoint:</strong> every criterion has a status and a piece of evidence you&#39;ve opened yourself (observed), not one an agent told you about.</p><h3 id="part-c--two-decisions-and-the-claims-audit-core-15-min" tabindex="-1">Part C — Two decisions and the claims audit (Core, 15 min) <a class="header-anchor" href="#part-c--two-decisions-and-the-claims-audit-core-15-min" aria-label="Permalink to &quot;Part C — Two decisions and the claims audit (Core, 15 min)&quot;">​</a></h3><p><strong>Two engineering decisions</strong> (section 5 of the report). For each:</p><ul><li><strong>The decision</strong>, in one sentence.</li><li><strong>The alternatives</strong> you considered, including the one an agent proposed if it did.</li><li><strong>The evidence</strong> for your choice: a test or mutation result, a benchmark you ran, a review comment, the parent project&#39;s guidance, a failed attempt recorded in <code>AI_LOG.md</code>.</li><li><strong>What you&#39;d watch for:</strong> the sign that the decision was wrong.</li></ul><p>Pick decisions you&#39;d defend out loud. The defense&#39;s team question is usually about one of them (<a href="./../../project/final-defense.html#in-the-slot">the final defense</a>).</p><p><strong>The claims audit</strong> (sections 4–6). Go through your notes for the evidence, decisions and process sections and tag every sentence that states a fact about the code, the tests, CI, the agents or your process as <strong>observed</strong> or <strong>inferred</strong>. Each inferred claim is either checked now or labeled inferred in the report. Apply the debate&#39;s test: is this a measured number or a feeling? &quot;The agent saved us time&quot; needs your week 13 data, or it becomes &quot;we felt faster; we didn&#39;t measure it&quot;.</p><p>You may use an agent to find support for claims (🟡 AI limited: AI may check claims against the fork). For example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: check the factual claims in our report draft against the repository.</span></span>
<span class="line"><span>Context: the repository is checked out at [commit]. Section 4 of our draft is below.</span></span>
<span class="line"><span>Task: for each sentence that states a fact about the code, tests, CI or our process,</span></span>
<span class="line"><span>find the file, test, workflow or commit that supports it and quote the relevant line.</span></span>
<span class="line"><span>If nothing supports it, write &quot;unsupported&quot;.</span></span>
<span class="line"><span>Constraints: don&#39;t rewrite the draft and don&#39;t edit any files.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[paste section 4]</span></span></code></pre></div><p>The agent&#39;s &quot;supported&quot; is itself inferred until you open the file and read the line.</p><p>✅ <strong>Checkpoint:</strong> two decisions drafted with alternatives and evidence; every factual sentence in sections 4–6 tagged, and the unsupported ones listed for the assignment.</p><h3 id="part-d--honest-limitations-if-time-510-min--ai-off" tabindex="-1">Part D — Honest limitations (If time, 5–10 min, 🔴 AI off) <a class="header-anchor" href="#part-d--honest-limitations-if-time-510-min--ai-off" aria-label="Permalink to &quot;Part D — Honest limitations (If time, 5–10 min, 🔴 AI off)&quot;">​</a></h3><p>The team writes this section without AI; it&#39;s graded on the Final&#39;s &quot;Honest limitations&quot; row (<a href="./../../assessment/rubrics.html#final-report-and-repository">rubric</a>). Start with notes:</p><ul><li><strong>Known issues:</strong> what doesn&#39;t work, and when.</li><li><strong>Threats to the validity of your own numbers:</strong><ul><li><em>Construct:</em> does the mutation score of the changed modules measure how well the contribution is tested? Does review time measured from PR timestamps include waiting?</li><li><em>Internal:</em> did a model or provider change between runs? Were tests written after the code, so they may agree with its bugs? Is a test flaky?</li><li><em>External:</em> would a result in your fork hold upstream, or with another model?</li></ul></li><li><strong>What you&#39;d do next,</strong> in order.</li></ul><p>The debate rewarded conceding a limit before someone else found it. The defense does too.</p><h3 id="screening-desk-your-first-upstream-pr-if-time" tabindex="-1">Screening desk: your first upstream PR (If time) <a class="header-anchor" href="#screening-desk-your-first-upstream-pr-if-time" aria-label="Permalink to &quot;Screening desk: your first upstream PR (If time)&quot;">​</a></h3><p>If you plan an optional upstream PR, bring it to the screening desk before you open it (<a href="./../../project/contribution-rules.html#optional-upstream-prs-tier-3">contribution rules</a>). Bring:</p><ul><li>☐ The project&#39;s AI policy (link) and what it requires; the stricter policy wins.</li><li>☐ The upstream issue, with a maintainer&#39;s response where the project expects one.</li><li>☐ The change, already reviewed by a teammate and green in your team fork&#39;s CI; small and focused.</li><li>☐ Your self-written description (🔴 AI off) and the disclosure in the project&#39;s format.</li><li>☐ Your answer to &quot;can you explain every line?&quot; Staff will pick one.</li></ul><p>Staff say <strong>go</strong> or <strong>not yet</strong> with a reason. One open upstream PR per student per project; you open it yourself, and no agent posts for you. A merge before the grade deadline earns a small bonus; nothing upstream ever costs you points (<a href="./../../project/contribution-rules.html#how-upstream-work-is-graded">how it&#39;s graded</a>). If every staff member is examining, come to office hours this week.</p><h3 id="checkoff-15-min" tabindex="-1">Checkoff (15 min) <a class="header-anchor" href="#checkoff-15-min" aria-label="Permalink to &quot;Checkoff (15 min)&quot;">​</a></h3><p>Labs and assignments are scored for weeks 1–13, so this checkoff isn&#39;t scored: staff record <strong>on track</strong> or <strong>needs help</strong>, and plan office hours from it. Because examiners are busy, a staff member starts checking teams from about 0:35. Show:</p><ul><li>☐ The evidence table, with a fresh-run value or a reason for every number.</li><li>☐ The status table, with evidence for each criterion.</li><li>☐ Two decisions drafted, and the list of unsupported claims.</li><li>☐ The commit hash the draft describes.</li><li>☐ Each member can name their own PRs and <code>AI_LOG.md</code> entries. The defense&#39;s individual questions come from them.</li></ul><p>If your exam slot took your Lab time, your team shows the rest, and you show your part (your PRs and <code>AI_LOG.md</code> entries) in office hours this week.</p><h3 id="next-steps-5-min" tabindex="-1">Next steps (5 min) <a class="header-anchor" href="#next-steps-5-min" aria-label="Permalink to &quot;Next steps (5 min)&quot;">​</a></h3><ul><li>The draft is due before the week 15 Seminar (below).</li><li>Week 15 has <strong>no quiz and no oral exam</strong> (Regulation H-1-a). Its Lab is an integration sprint and an ungraded defense dry run (<a href="./../15-ship-and-reflect/">week 15</a>).</li><li>Haven&#39;t taken oral exam 2? Talk to the instructor today.</li></ul><h2 id="assignment--the-final-report-draft" tabindex="-1">Assignment — The Final Report Draft <a class="header-anchor" href="#assignment--the-final-report-draft" aria-label="Permalink to &quot;Assignment — The Final Report Draft&quot;">​</a></h2><p><strong>Team · on Canvas · 🟡 AI limited</strong> (AI may help with tables, figures and checking claims against the fork; 🔴 AI off for the limitations, contributions and reflection sections) · <strong>feedback, not scored</strong>.</p><p>The draft has the outline of the final report, filled in as far as it can be now. Staff use it to write your final defense questions, so a thin draft means questions you didn&#39;t prepare for.</p><h3 id="deliverables" tabindex="-1">Deliverables <a class="header-anchor" href="#deliverables" aria-label="Permalink to &quot;Deliverables&quot;">​</a></h3><ul><li>☐ <strong>The draft</strong> (one PDF or Markdown file) with the nine sections of the <a href="./../../project/milestones.html#the-final-report">final report</a>: sections 2–6 filled in as far as they can be (status against the spec, how to reproduce, evidence, two engineering decisions, process and AI use), and at least notes for sections 1 and 7–9. At the top: the team fork&#39;s URL and the <strong>commit</strong> the draft describes.</li><li>☐ <strong>The evidence table</strong> from Part A, as an appendix: every number, its command or CI run, and the fresh-run value.</li><li>☐ <strong>In the team fork:</strong> README fixes from the grader&#39;s walk, and the one documented command committed and working on <code>main</code>.</li><li>☐ <strong><code>course/AI_LOG.md</code> current</strong> for every member&#39;s sessions since M2, with what was delegated and what your checks caught.</li><li>☐ <strong>CS [5xxx]:</strong> the study paper draft, submitted separately on Canvas (<a href="./../../graduate/empirical-study.html#milestones">empirical study</a>).</li><li>☐ <strong>Everyone:</strong> the week 15 reading response (<a href="./../15-ship-and-reflect/">week 15</a>).</li></ul><h3 id="steps-about-56-hours-across-the-team" tabindex="-1">Steps (about 5–6 hours across the team) <a class="header-anchor" href="#steps-about-56-hours-across-the-team" aria-label="Permalink to &quot;Steps (about 5–6 hours across the team)&quot;">​</a></h3><ol><li><strong>Finish Parts A–C</strong> for anything the Lab didn&#39;t reach, and fix every README bug the Reproducer found.</li><li><strong>Write sections 2–4</strong> from the status and evidence tables. Section 3 is the exact command and what it should print.</li><li><strong>Write section 5</strong> from Part C&#39;s two decisions.</li><li><strong>Write section 6</strong>, process and AI use: a summary of <code>course/AI_LOG.md</code> (what you delegated, what verification caught, with examples, and what the agents couldn&#39;t do) and the data from your week 13 retrospective. Report measurements as measurements and impressions as impressions.</li><li><strong>Sections 7–9</strong> (🔴 AI off, written by the team): notes at least on limitations and threats to validity; the contribution table by GitHub username with PR numbers; what you&#39;d do differently.</li><li><strong>Read it as an evidence judge would.</strong> Every number has a source in the repository and, where it varies, its uncertainty. No self-report presented as a measurement. Every inferred claim is labeled. Nothing contradicts the tagged history.</li><li><strong>Submit on Canvas.</strong> One member submits for the team.</li></ol><h3 id="how-its-graded" tabindex="-1">How it&#39;s graded <a class="header-anchor" href="#how-its-graded" aria-label="Permalink to &quot;How it&#39;s graded&quot;">​</a></h3><p>The draft isn&#39;t scored. Staff return written comments against the Final&#39;s report rows (demonstrated behavior, reproducible checks, engineering decisions, honest limitations, process and AI use; <a href="./../../assessment/rubrics.html#final-report-and-repository">rubric</a>), aiming for the week 15 Lab so you can use them in the dry run. A team that doesn&#39;t submit a draft <strong>loses 3 of the Final&#39;s 35 report points</strong> (<a href="./../../project/milestones.html#the-full-timeline">milestones</a>). Grace tokens don&#39;t apply: individual tokens can&#39;t extend team work, and the team token covers M0–M2 only (<a href="./../../assessment/#late-work-and-grace-tokens">late work</a>).</p><p><strong>Due before next week&#39;s Seminar (default 11:59 pm the night before).</strong></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Minimum to keep up:</strong> sections 2–4 of the draft (status, the reproduce command, the evidence table) with the commit they describe, checked by a teammate in a fresh Codespace; and oral exam 2 taken this week. Taking both oral exams and the final defense is required for a C or higher (<a href="./../../assessment/#letter-grades">letter grades</a>). If your team is behind, shrink the claim to what you can show: a smaller contribution you can reproduce and explain beats a larger one you can&#39;t.</p></div>`,63)])])}const m=t(n,[["render",r]]);export{p as __pageData,m as default};
